<?php
declare(strict_types=1);
?>
<div class="admin-page"><div class="admin-page-header"><div><p class="eyebrow">Gestructureerde kennis</p><h1>Scam-taxonomie</h1><p>Families → types → varianten → indicatoren.</p></div></div><?php foreach ($families as $family): ?><section class="admin-card" style="margin-bottom:16px"><h2><?= e($family['name']) ?></h2><p class="form-help"><?= e($family['summary']) ?></p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Scamtype</th><th>Status</th><th>Varianten</th><th>Slug</th></tr></thead><tbody><?php foreach ($types as $type): if ((int) $type['family_id'] !== (int) $family['id']) continue; ?><tr><td><strong><?= e($type['name']) ?></strong></td><td><span class="tag tag-green"><?= e(status_label((string) $type['status'])) ?></span></td><td><?php $count = 0; foreach ($variants as $variant) { if ((int) $variant['type_id'] === (int) $type['id']) $count++; } echo e((string) $count); ?></td><td><code><?= e($type['slug']) ?></code></td></tr><?php endforeach; ?></tbody></table></div></section><?php endforeach; ?></div>
